<script setup lang="ts">
import {ref,onMounted,inject} from 'vue'
import {Bell,Check,RefreshCw} from 'lucide-vue-next'
import {api,date,describeError,type Data} from '../api'
const emit=defineEmits<{unread:[count:number]}>(),open=inject<(id:string)=>void>('openActivity')!
const rows=ref<Data[]>([]),unreadOnly=ref(false),cursor=ref<string|null>(null),busy=ref(false),error=ref(''),count=ref(0)
async function load(more=false){busy.value=true;error.value='';try{const p=await api(`/notifications?unreadOnly=${unreadOnly.value}&pageSize=20${more&&cursor.value?'&cursor='+encodeURIComponent(cursor.value):''}`);rows.value=more?[...rows.value,...p.items]:p.items;cursor.value=p.nextCursor;count.value=p.unreadCount;emit('unread',p.unreadCount)}catch(e){error.value=describeError(e)}finally{busy.value=false}}
async function read(n:Data){try{await api(`/notifications/${n.id}/read`,'PUT',{});await load()}catch(e){error.value=describeError(e)}}
onMounted(()=>load())
</script>
<template><div class="page-heading"><div><span class="eyebrow">EVERY PLAN HAS A RESPONSE</span><h1>通知中心</h1><p>申请结果、活动变化与每一次回应，都在这里。</p></div><button class="secondary" @click="load()"><RefreshCw :size="16"/>刷新</button></div><div class="tabs"><button :class="['chip',{active:!unreadOnly}]" @click="unreadOnly=false;load()">全部通知</button><button :class="['chip',{active:unreadOnly}]" @click="unreadOnly=true;load()">未读 {{count}}</button></div><p class="field-help">站内通知持续保留。外部推送为模拟渠道，其“受理”不代表已经送达或已读。</p><div v-if="error" class="error-box" role="alert">{{error}}</div><section class="panel"><article v-for="n in rows" :key="n.id" :class="['notice','list-row',{unread:!n.readAt}]"><span class="notice-symbol"><Bell :size="18"/></span><div class="notice-body"><h3>{{n.payload.message||'你有一条新的通知'}}</h3><p v-if="n.payload.title" class="muted">{{n.payload.title}}</p><p class="subtle">{{date(n.createdAt)}}</p><div class="actions"><button v-if="n.payload.activityId" class="text-button" @click="open(n.payload.activityId)">查看活动</button><button v-if="!n.readAt" class="text-button" @click="read(n)"><Check :size="14"/>标为已读</button><span v-else class="subtle">已读</span></div></div></article><div v-if="!rows.length&&!busy&&!error" class="empty-state"><Bell :size="33"/><h2>{{unreadOnly?'暂时没有未读通知':'还没有新的回应'}}</h2><p>申请与行动的进展会及时记录在这里。</p></div><p v-if="busy" class="loading">正在加载通知…</p></section><button v-if="cursor" class="secondary load-more" :disabled="busy" @click="load(true)">加载更早通知</button></template>
